def verifier(assign):
    # Verify domain constraints and compute the unique solution.
    # Return (True, answer) if valid; else (False, None).
    try:
        base = int(assign['base'])
        m = int(assign['m_digits'])
        n = int(assign['n_digits'])
        p = int(assign['p'])
        r = int(assign['r'])
    except Exception:
        # Missing or malformed assignments
        return (False, None)
    # Basic domain checks
    if not (base >= 8 and 2 <= m <= 4 and 3 <= n <= 5 and p >= 7):
        # Domain outside intended harder regime
        return (False, None)
    if not (0 < r < base ** n):
        # r must be strictly between 0 and base^n
        return (False, None)
    # Enumerate all solutions using the derived number-theoretic structure
    def divisors(n):
        ds = set()
        i = 1
        while i * i <= n:
            if n % i == 0:
                ds.add(i)
                ds.add(n // i)
            i += 1
        return sorted(ds)
    D = base ** n - r
    # Hardness: ensure D has sufficiently rich divisor structure
    def dcount(n):
        cnt = 0
        i = 1
        while i * i <= n:
            if n % i == 0:
                cnt += 1 if i * i == n else 2
            i += 1
        return cnt
    if dcount(D) < 16:
        # Too few divisors; instance may be too trivial
        return (False, None)
    X_low = base ** (m - 1)
    X_high = base ** m - 1
    Y_low = base ** (n - 1)
    Y_high = base ** n - 1
    sols = []
    for dd in divisors(D):
        if (dd + 1) % p != 0:
            continue
        X_candidate = (dd + 1) // p
        if not (X_low <= X_candidate <= X_high):
            continue
        # Y from formula
        Y_candidate = X_candidate * D // dd
        if not (Y_low <= Y_candidate <= Y_high):
            continue
        # Check the defining equation
        lhs = X_candidate * (base ** n) + Y_candidate
        rhs = p * X_candidate * Y_candidate + r * X_candidate
        if lhs == rhs:
            sols.append((X_candidate, Y_candidate))
    if len(sols) != 1:
        # Must be unique to avoid guessing or ambiguity
        return (False, None)
    X_sol, Y_sol = sols[0]
    answer = X_sol + Y_sol
    return (True, answer)
